pseudocode:
class Node { constructor(url) { this.url = url; this.next = null; this.prev = null; } }
class BrowserHistory { constructor(homepage) { this.curr = new Node(homepage); }
visit(url) { let newNode = new Node(url); newNode.prev = this.curr; this.curr.next = newNode; this.curr = newNode; }
back(steps) { while (steps > 0 && this.curr.prev) { this.curr = this.curr.prev; steps--; } return this.curr.url; }
forward(steps) { while (steps > 0 && this.curr.next) { this.curr = this.curr.next; steps--; } return this.curr.url; } }
